INSERT INTO Promotions (Id, Code, Name, Description, DiscountType, DiscountValue, MaxDiscountAmount, StartDate, EndDate, Status, CreatedAt) VALUES
(1, N'TET2025', N'Lunar New Year 2025 Special', N'Celebrate the Year of the Snake with exclusive savings on all tour packages departing during Tet holiday.', 'Percentage', 20, 2000000, '2025-01-15 00:00:00', '2025-02-05 23:59:59', 'Active', GETDATE()),
(2, N'SUMMER25', N'Summer Vibes Beach Deals 2025', N'Hot summer promotions for coastal and island tours throughout June to August 2025.', 'Percentage', 15, 1500000, '2025-06-01 00:00:00', '2025-08-31 23:59:59', 'Active', GETDATE()),
(3, N'QUOCKHANH25', N'National Day 2-9 Holiday Sale', N'Exclusive discounts for long weekend tours during the September 2nd National Day holiday.', 'FixedAmount', 500000, NULL, '2025-08-25 00:00:00', '2025-09-05 23:59:59', 'Active', GETDATE()),
(4, N'MIDAUTUMN25', N'Mid-Autumn Festival Special', N'Romantic tours for couples and family bonding during the beautiful Mid-Autumn lantern festival season.', 'Percentage', 10, 1000000, '2025-09-20 00:00:00', '2025-10-10 23:59:59', 'Active', GETDATE()),
(5, N'EARLYBIRD25', N'Early Bird Booking Discount 2025', N'Book any tour 60 days in advance and enjoy significant savings. Limited seats available.', 'Percentage', 12, 1200000, '2025-01-01 00:00:00', '2025-12-31 23:59:59', 'Active', GETDATE()),
(6, N'WINTER25', N'Winter Highlands & Cloud Season', N'Discover the misty beauty of Vietnam''s northern highlands during the stunning winter cloud season.', 'FixedAmount', 700000, NULL, '2025-11-01 00:00:00', '2025-12-31 23:59:59', 'Active', GETDATE()),
(7, N'FLASH30APR', N'Liberation Day Flash Sale', N'48-hour flash sale celebrating April 30th Liberation Day. Massive discounts for spontaneous travelers.', 'Percentage', 25, 2500000, '2025-04-28 00:00:00', '2025-04-30 23:59:59', 'Active', GETDATE()),
(8, N'BACKTOSCHOOL', N'Back to School Family Tours', N'Educational and fun family tours at special rates as school season begins in September.', 'Percentage', 10, 1000000, '2025-09-01 00:00:00', '2025-09-20 23:59:59', 'Active', GETDATE()),
(9, N'TET2026', N'Lunar New Year 2026 Early Deal', N'Secure your Tet 2026 holiday tours at the best prices with our early reservation promotion.', 'Percentage', 18, 1800000, '2025-12-01 00:00:00', '2026-02-15 23:59:59', 'Active', GETDATE()),
(10, N'SUMMER26', N'Summer Adventure Deals 2026', N'Comprehensive summer promotions for adventure-seekers and beach lovers planning their 2026 vacation.', 'Percentage', 15, 1500000, '2026-05-15 00:00:00', '2026-08-31 23:59:59', 'Active', GETDATE()),
(11, N'LASTMIN25', N'Last Minute Weekend Getaway', N'Snag incredible last-minute deals for weekend departures. Perfect for spontaneous explorers.', 'FixedAmount', 300000, NULL, '2025-01-01 00:00:00', '2025-12-31 23:59:59', 'Active', GETDATE()),
(12, N'PHUQUY2025', N'Phu Quoc Paradise Summer Festival', N'Special bundle deals for Phu Quoc including accommodation and island hopping activities.', 'Percentage', 20, 2000000, '2025-04-01 00:00:00', '2025-07-31 23:59:59', 'Active', GETDATE()),
(13, N'HANOI625', N'Hanoi Liberation Day Special', N'Commemorating the 71st anniversary of Hanoi Liberation with exclusive discounts on capital city tours.', 'FixedAmount', 600000, NULL, '2025-10-05 00:00:00', '2025-10-15 23:59:59', 'Active', GETDATE()),
(14, N'SAPADISCOVER', N'Discover Sapa Rice Harvest Season', N'The most beautiful time to visit Sapa - golden terraced rice fields in full harvest glory.', 'Percentage', 12, 1200000, '2025-09-01 00:00:00', '2025-11-30 23:59:59', 'Active', GETDATE()),
(15, N'HONEYMOON25', N'Romantic Honeymoon Package Deal', N'Specially curated honeymoon packages with exclusive romantic add-ons for newlyweds.', 'Percentage', 15, 2000000, '2025-01-01 00:00:00', '2025-12-31 23:59:59', 'Active', GETDATE()),
(16, N'STUDENT2025', N'Student & Youth Explorer Discount', N'Exclusive discounts for students and young travelers aged 18-25 on selected educational tour packages.', 'Percentage', 20, 1500000, '2025-01-01 00:00:00', '2025-12-31 23:59:59', 'Active', GETDATE()),
(17, N'MEKONG25', N'Mekong Delta Flood Season Discovery', N'Experience the magical floating villages and golden sesbania flowers during the annual flood season.', 'FixedAmount', 400000, NULL, '2025-09-15 00:00:00', '2025-11-15 23:59:59', 'Active', GETDATE()),
(18, N'XMAS2025', N'Christmas & Year-End Celebration Tours', N'Festive year-end tours with special Christmas and New Year countdown experiences across Vietnam.', 'Percentage', 10, 1000000, '2025-12-20 00:00:00', '2026-01-05 23:59:59', 'Active', GETDATE()),
(19, N'CBDAY26', N'Reunification Day Long Weekend 2026', N'Long weekend tour packages for the April 30 & May 1 holiday in 2026.', 'Percentage', 20, 2000000, '2026-04-25 00:00:00', '2026-05-02 23:59:59', 'Active', GETDATE()),
(20, N'SPRING26', N'Spring Blossom Season 2026', N'Witness Vietnam''s spectacular spring blossom displays from Da Lat to Moc Chau at special rates.', 'Percentage', 15, 1500000, '2026-01-20 00:00:00', '2026-03-15 23:59:59', 'Active', GETDATE());
